diff --git a/core/src/Kokkos_MathematicalFunctions.hpp b/core/src/Kokkos_MathematicalFunctions.hpp
index f0a369dd44c..3a36486fab3 100644
--- a/core/src/Kokkos_MathematicalFunctions.hpp
+++ b/core/src/Kokkos_MathematicalFunctions.hpp
@@ -218,6 +218,51 @@ using promote_3_t = typename promote_3<T, U, V>::type;
     return FUNC(static_cast<Promoted>(x), static_cast<Promoted>(y));           \
   }

+#define KOKKOS_IMPL_MATH_TERNARY_INT_PTR_FUNCTION(FUNC)                        \
+  KOKKOS_INLINE_FUNCTION float FUNC(float x, float y, int* z) {                \
+    using KOKKOS_IMPL_MATH_FUNCTIONS_NAMESPACE::FUNC;                          \
+    return FUNC(x, y, z);                                                      \
+  }                                                                            \
+  KOKKOS_INLINE_FUNCTION double FUNC(double x, double y, int* z) {             \
+    using KOKKOS_IMPL_MATH_FUNCTIONS_NAMESPACE::FUNC;                          \
+    return FUNC(x, y, z);                                                      \
+  }                                                                            \
+  inline long double FUNC(long double x, long double y, int* z) {              \
+    using std::FUNC;                                                           \
+    return FUNC(x, y, z);                                                      \
+  }                                                                            \
+  KOKKOS_INLINE_FUNCTION float FUNC##f(float x, float y, int* z) {             \
+    using KOKKOS_IMPL_MATH_FUNCTIONS_NAMESPACE::FUNC;                          \
+    return FUNC(x, y, z);                                                      \
+  }                                                                            \
+  inline long double FUNC##l(long double x, long double y, int* z) {           \
+    using std::FUNC;                                                           \
+    return FUNC(x, y, z);                                                      \
+  }                                                                            \
+  template <class T1, class T2>                                                \
+  KOKKOS_INLINE_FUNCTION                                                       \
+      std::enable_if_t<std::is_arithmetic_v<T1> && std::is_arithmetic_v<T2> && \
+                           !std::is_same_v<T1, long double> &&                 \
+                           !std::is_same_v<T2, long double>,                   \
+                       Kokkos::Impl::promote_2_t<T1, T2>>                      \
+      FUNC(T1 x, T2 y, int* z) {                                               \
+    using Promoted = Kokkos::Impl::promote_2_t<T1, T2>;                        \
+    using KOKKOS_IMPL_MATH_FUNCTIONS_NAMESPACE::FUNC;                          \
+    return FUNC(static_cast<Promoted>(x), static_cast<Promoted>(y), z);        \
+  }                                                                            \
+  template <class T1, class T2>                                                \
+  inline std::enable_if_t<std::is_arithmetic_v<T1> &&                          \
+                              std::is_arithmetic_v<T2> &&                      \
+                              (std::is_same_v<T1, long double> ||              \
+                               std::is_same_v<T2, long double>),               \
+                          long double>                                         \
+  FUNC(T1 x, T2 y, int* z) {                                                   \
+    using Promoted = Kokkos::Impl::promote_2_t<T1, T2>;                        \
+    static_assert(std::is_same_v<Promoted, long double>);                      \
+    using std::FUNC;                                                           \
+    return FUNC(static_cast<Promoted>(x), static_cast<Promoted>(y), z);        \
+  }
+
 #define KOKKOS_IMPL_MATH_TERNARY_FUNCTION(FUNC)                             \
   KOKKOS_INLINE_FUNCTION float FUNC(float x, float y, float z) {            \
     using KOKKOS_IMPL_MATH_FUNCTIONS_NAMESPACE::FUNC;                       \
@@ -314,7 +359,7 @@ inline long double abs(long double x) {
 KOKKOS_IMPL_MATH_UNARY_FUNCTION(fabs)
 KOKKOS_IMPL_MATH_BINARY_FUNCTION(fmod)
 KOKKOS_IMPL_MATH_BINARY_FUNCTION(remainder)
-// remquo
+KOKKOS_IMPL_MATH_TERNARY_INT_PTR_FUNCTION(remquo)
 KOKKOS_IMPL_MATH_TERNARY_FUNCTION(fma)
 KOKKOS_IMPL_MATH_BINARY_FUNCTION(fmax)
 KOKKOS_IMPL_MATH_BINARY_FUNCTION(fmin)
diff --git a/core/unit_test/TestMathematicalFunctions.hpp b/core/unit_test/TestMathematicalFunctions.hpp
index d41163b232b..321a817ec6b 100644
--- a/core/unit_test/TestMathematicalFunctions.hpp
+++ b/core/unit_test/TestMathematicalFunctions.hpp
@@ -511,6 +511,37 @@ DEFINE_BINARY_FUNCTION_EVAL(fmin, 0);

 #undef DEFINE_BINARY_FUNCTION_EVAL

+#define DEFINE_TERNARY_INT_PTR_FUNCTION_EVAL(FUNC, ULP_FACTOR)              \
+  struct MathTernaryIntPtrFunction_##FUNC {                                 \
+    template <typename T, typename U>                                       \
+    static KOKKOS_FUNCTION auto eval(T x, U y, int* z) {                    \
+      static_assert(                                                        \
+          std::is_same_v<decltype(Kokkos::FUNC((T)0, (U)0, (int*)nullptr)), \
+                         math_binary_function_return_type_t<T, U>>);        \
+      return Kokkos::FUNC(x, y, z);                                         \
+    }                                                                       \
+    template <typename T, typename U>                                       \
+    static auto eval_std(T x, U y, int* z) {                                \
+      static_assert(                                                        \
+          std::is_same_v<decltype(std::FUNC((T)0, (U)0, (int*)nullptr)),    \
+                         math_binary_function_return_type_t<T, U>>);        \
+      return std::FUNC(x, y, z);                                            \
+    }                                                                       \
+    static KOKKOS_FUNCTION int ulp_factor() { return ULP_FACTOR; }          \
+  };                                                                        \
+  using kk3_##FUNC = MathTernaryIntPtrFunction_##FUNC;                      \
+  template <>                                                               \
+  struct math_function_name<MathTernaryIntPtrFunction_##FUNC> {             \
+    static constexpr char name[] = #FUNC;                                   \
+  };                                                                        \
+  constexpr char math_function_name<MathTernaryIntPtrFunction_##FUNC>::name[]
+
+#ifndef KOKKOS_MATHEMATICAL_FUNCTIONS_SKIP_2
+DEFINE_TERNARY_INT_PTR_FUNCTION_EVAL(remquo, 0);
+#endif
+
+#undef DEFINE_TERNARY_INT_PTR_FUNCTION_EVAL
+
 #define DEFINE_TERNARY_FUNCTION_EVAL(FUNC, ULP_FACTOR)                   \
   struct MathTernaryFunction_##FUNC {                                    \
     template <typename T, typename U, typename V>                        \
@@ -728,6 +759,46 @@ void do_test_math_binary_function(Arg1 arg1, Arg2 arg2) {
       (TestMathBinaryFunction<Space, Func, Arg1, Arg2>(arg1, arg2), 0)...};
 }

+template <class Space, class Func, class Arg1, class Arg2,
+          class Ret = math_binary_function_return_type_t<Arg1, Arg2>>
+struct TestMathTernaryIntPtrFunction : FloatingPointComparison {
+  Arg1 val1_;
+  Arg2 val2_;
+  int val_;
+  Ret res_;
+  TestMathTernaryIntPtrFunction(Arg1 val1, Arg2 val2)
+      : val1_(val1), val2_(val2), res_(Func::eval_std(val1, val2, &val_)) {
+    run();
+  }
+  void run() {
+    int errors = 0;
+    Kokkos::parallel_reduce(Kokkos::RangePolicy<Space>(0, 1), *this, errors);
+    ASSERT_EQ(errors, 0) << "Failed check no error for "
+                         << math_function_name<Func>::name << "("
+                         << type_helper<Arg1>::name() << ", "
+                         << type_helper<Arg2>::name() << ")";
+  }
+  KOKKOS_FUNCTION void operator()(int, int& e) const {
+    int val;
+    auto res  = Func::eval(val1_, val2_, &val);
+    bool ar_1 = compare(res, res_, Func::ulp_factor());
+    bool ar_2 = (val_ == val);
+    if (!(ar_1 && ar_2)) {
+      ++e;
+      Kokkos::printf(
+          "value at %f, %f which is %f and %i was expected to be %f and %i\n",
+          (double)val1_, (double)val2_, (double)res, val, (double)res_, val_);
+    }
+  }
+};
+
+template <class Space, class... Func, class Arg1, class Arg2>
+void do_test_math_ternary_int_ptr_function(Arg1 arg1, Arg2 arg2) {
+  (void)std::initializer_list<int>{
+      (TestMathTernaryIntPtrFunction<Space, Func, Arg1, Arg2>(arg1, arg2),
+       0)...};
+}
+
 template <class Space, class Func, class Arg1, class Arg2, class Arg3,
           class Ret = math_ternary_function_return_type_t<Arg1, Arg2, Arg3>>
 struct TestMathTernaryFunction : FloatingPointComparison {
@@ -748,7 +819,7 @@ struct TestMathTernaryFunction : FloatingPointComparison {
     ASSERT_EQ(errors, 0) << "Failed check no error for "
                          << math_function_name<Func>::name << "("
                          << type_helper<Arg1>::name() << ", "
-                         << type_helper<Arg1>::name() << ", "
+                         << type_helper<Arg2>::name() << ", "
                          << type_helper<Arg3>::name() << ")";
   }
   KOKKOS_FUNCTION void operator()(int, int& e) const {
@@ -942,6 +1013,15 @@ TEST(TEST_CATEGORY, mathematical_functions_fma) {
 #endif
 }

+TEST(TEST_CATEGORY, mathematical_functions_remquo) {
+  do_test_math_ternary_int_ptr_function<TEST_EXECSPACE, kk3_remquo>(2.f, 3.f);
+  do_test_math_ternary_int_ptr_function<TEST_EXECSPACE, kk3_remquo>(2., 3.);
+  do_test_math_ternary_int_ptr_function<TEST_EXECSPACE, kk3_remquo>(2, 3);
+#ifdef MATHEMATICAL_FUNCTIONS_HAVE_LONG_DOUBLE_OVERLOADS
+  do_test_math_ternary_int_ptr_function<TEST_EXECSPACE, kk3_remquo>(2.l, 3.l);
+#endif
+}
+
 TEST(TEST_CATEGORY, mathematical_functions_fmax_fmin) {
   do_test_math_binary_function<TEST_EXECSPACE, kk_fmax>(
       static_cast<KE::half_t>(2.f), static_cast<KE::half_t>(3.f));

